    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kamar | Asrama Putri Junjung Buyah Kukar YK</title>
    <style>
        :root { --ink: #171717; --muted: #737373; --line: #e5e5e5; --soft: #fafafa; --yellow: #ffe51f; --green: #078455; --red: #b42318; }
        * { box-sizing: border-box; } body { margin: 0; color: var(--ink); background: #fff; font-family: Inter, system-ui, sans-serif; } a { color: inherit; text-decoration: none; } button, input { font: inherit; }
        .topbar { height: 61px; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 0 25px; border-bottom: 1px solid var(--line); } .brand { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: 14px; white-space: nowrap; } .brand img { width: 28px; height: 28px; border-radius: 50%; object-fit: cover; } .brand strong { color: var(--ink); } .top-search { display: flex; align-items: center; gap: 10px; width: min(385px, 34vw); padding: 9px 12px; border: 1px solid var(--line); border-radius: 8px; color: #999; } .top-search input { width: 100%; border: 0; outline: 0; font-size: 13px; } .shortcut { padding: 3px 7px; border: 1px solid var(--line); border-radius: 4px; font-size: 10px; } .top-actions { display: flex; gap: 8px; } .icon-button { width: 39px; height: 39px; border: 1px solid var(--line); border-radius: 8px; color: var(--muted); background: #fff; }
        main { max-width: 1650px; margin: auto; padding: 29px 21px 60px; } h1 { margin: 0; font-size: 25px; letter-spacing: -.04em; } .intro { margin: 6px 0 24px; color: var(--muted); font-size: 14px; } .page-head { display: flex; align-items: end; justify-content: space-between; gap: 20px; } .head-actions { display: flex; gap: 8px; } .button { padding: 10px 14px; border: 1px solid var(--line); border-radius: 7px; color: var(--ink); background: #fff; font-size: 12px; font-weight: 800; cursor: pointer; } .button.primary { border-color: var(--ink); color: #fff; background: var(--ink); }
        .notice, .errors { margin-bottom: 16px; padding: 12px 15px; border-radius: 8px; font-size: 13px; } .notice { color: #166534; background: #ecfdf5; } .errors { color: var(--red); background: #fff1f1; }
        .add-panel { display: none; margin: 20px 0; padding: 22px; border: 1px solid var(--line); border-radius: 16px; background: linear-gradient(145deg,#fff,#f3f8e8); box-shadow: var(--shadow); } .add-panel.open { display: block; } .add-panel h2 { margin: 0 0 15px; font-size: 17px; } .add-form { display: flex; align-items: end; gap: 10px; } .add-form label { display: grid; gap: 6px; color: #666; font-size: 11px; font-weight: 800; } .add-form input { width: 220px; padding: 10px; border: 1px solid #ddd; border-radius: 7px; }
        .panel { overflow: hidden; border: 1px solid var(--line); border-radius: 7px; } .panel-top { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 15px 20px; border-bottom: 1px solid var(--line); } .tabs { display: flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: 7px; } .tab { padding: 9px 15px; border-radius: 5px; color: #555; font-size: 12px; font-weight: 700; } .tab.active { color: #fff; background: var(--ink); } .count { color: var(--muted); font-size: 12px; }
        .rooms { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; padding: 20px; background: #fcfcfc; } .room { padding: 20px; border: 1px solid var(--line); border-radius: 11px; background: #fff; } .room-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 16px; } .room-number { font-size: 20px; font-weight: 850; } .room-name { margin-top: 3px; color: var(--muted); font-size: 12px; } .resident-actions { display: flex; gap: 5px; margin-left: auto; } .resident-actions button { padding: 5px 7px; border: 1px solid var(--line); border-radius: 6px; color: var(--muted); background: transparent; font-size: 10px; cursor: pointer; } .resident-actions button:hover { color: var(--ink); background: #fff; } .room-status { padding: 5px 9px; border-radius: 99px; color: #9a6500; background: #fff8da; font-size: 10px; font-weight: 800; white-space: nowrap; } .room-label { display: block; margin-top: 4px; color: var(--muted); font-size: 12px; } .status { padding: 5px 9px; border-radius: 99px; color: var(--green); background: #eafaf2; font-size: 10px; font-weight: 800; white-space: nowrap; } .status.full { color: var(--red); background: #fff0f0; } .status.almost { color: #9a6500; background: #fff8da; } .bar { height: 6px; margin-bottom: 17px; overflow: hidden; border-radius: 99px; background: #eee; } .bar span { display: block; height: 100%; border-radius: inherit; background: var(--yellow); } .edit-room { margin-bottom: 17px; } .edit-room summary { color: var(--muted); font-size: 11px; font-weight: 800; cursor: pointer; } .edit-form { display: grid; gap: 9px; margin-top: 12px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--soft); } .edit-form label { display: grid; gap: 5px; color: var(--muted); font-size: 10px; font-weight: 800; } .edit-form input { width: 100%; padding: 8px; border: 1px solid #ddd; border-radius: 6px; } .edit-form .button { padding: 8px 10px; } .residents { display: grid; gap: 8px; } .resident { display: flex; align-items: center; gap: 9px; padding: 9px; border-radius: 7px; background: var(--soft); font-size: 12px; font-weight: 700; } .avatar { display: grid; width: 28px; height: 28px; place-items: center; border-radius: 50%; background: var(--yellow); font-size: 11px; } .empty { padding: 25px; color: var(--muted); text-align: center; } .rooms > .empty { grid-column: 1 / -1; }
        @media (max-width: 900px) { .top-search { display: none; } .page-head { align-items: flex-start; flex-direction: column; } .head-actions { width: 100%; } .head-actions .button { flex: 1; } .rooms { grid-template-columns: repeat(2, 1fr); } } @media (max-width: 550px) { main { padding: 24px 14px; } .rooms { grid-template-columns: 1fr; padding: 12px; } .panel-top { align-items: flex-start; flex-direction: column; } .tabs { width: 100%; } .tab { flex: 1; text-align: center; } .add-form { align-items: stretch; flex-direction: column; } .add-form input { width: 100%; } }
        html[data-theme="dark"] body { color: #f4f4f4; background: #111; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .add-panel, html[data-theme="dark"] .room { background: #191919; border-color: #333; } html[data-theme="dark"] .top-search, html[data-theme="dark"] .icon-button, html[data-theme="dark"] .button { color: #eee; background: #191919; border-color: #444; } html[data-theme="dark"] input { color: #eee; background: #222; border-color: #444; } html[data-theme="dark"] .rooms { background: #141414; } html[data-theme="dark"] .resident { background: #222; } html[data-theme="dark"] .brand strong, html[data-theme="dark"] h1, html[data-theme="dark"] h2 { color: #fff; }
        :root { --ink: #17201d; --muted: #68736f; --line: #e5e9e6; --soft: #f7f9f6; --yellow: #d8ff27; --gold: #b58a36; --shadow: 0 18px 45px rgba(23,32,29,.09); }
        body { background: radial-gradient(circle at 90% 0, #e9f7c8 0, transparent 28%), #f4f7f3; } .topbar { position: sticky; top: 0; z-index: 4; height: 68px; padding: 0 34px; background: rgba(255,255,255,.9); backdrop-filter: blur(16px); } main { max-width: 1560px; padding: 42px 34px 70px; } .page-head { margin-bottom: 30px; } .page-head h1 { font-size: clamp(28px,3vw,36px); letter-spacing: -.06em; } .panel { overflow: hidden; border-radius: 20px; background: rgba(255,255,255,.82); box-shadow: var(--shadow); } .panel-top { padding: 18px 22px; background: linear-gradient(90deg,#ffffff,#f4f9df); } .tabs { border-color: #dfe7d9; border-radius: 12px; background: rgba(255,255,255,.7); } .tab { padding: 10px 17px; border-radius: 8px; } .tab.active { background: var(--ink); box-shadow: 0 6px 16px #17201d26; } .rooms { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; padding: 22px; background: #f8faf7; } .room { position: relative; min-height: 280px; padding: 22px; border: 1px solid #e0e8df; border-radius: 17px; background: linear-gradient(145deg,#fff 0%,#fbfdf9 72%,#f2f7e7 100%); box-shadow: 0 8px 24px rgba(23,32,29,.06); transition: transform .2s, box-shadow .2s, border-color .2s; } .room:hover { transform: translateY(-3px); border-color: #cbd9b9; box-shadow: 0 18px 36px rgba(23,32,29,.12); } .room-head { margin-bottom: 19px; } .room-number { font-size: 22px; letter-spacing: -.04em; } .room-name { color: var(--gold); font-weight: 750; } .room-label { margin-top: 6px; color: var(--muted); } .status { padding: 6px 11px; letter-spacing: .04em; box-shadow: inset 0 0 0 1px #ffffff80; } .bar { height: 8px; margin-bottom: 19px; background: #e7ece6; } .bar span { background: linear-gradient(90deg,#b8ef00,#d8ff27); } .edit-room { padding: 12px 0; border-top: 1px solid #edf1eb; border-bottom: 1px solid #edf1eb; } .edit-room summary { color: #4c5c53; } .residents { gap: 9px; margin-top: 18px; } .residents > strong { color: #36453d; font-size: 12px; letter-spacing: .08em; text-transform: uppercase; } .resident { min-height: 46px; padding: 8px 10px; border: 1px solid #e7eee5; border-radius: 11px; background: #f7faf5; } .resident span:nth-child(2) { color: #24332b; font-size: 13px; } .avatar { width: 32px; height: 32px; color: #17201d; background: var(--yellow); font-weight: 850; } .resident-actions { align-items: center; } .resident-actions button { border-color: #d7e2d4; background: #fff; } .resident-actions button:hover { color: var(--ink); background: #f0f7d7; } .empty { padding: 22px 10px; color: #87938c; font-size: 12px; }
        html[data-theme="dark"] body { color: #f3f7f4; background: #101412; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .add-panel { background: #1a211e; border-color: #35413b; } html[data-theme="dark"] .panel-top { background: linear-gradient(90deg,#1a211e,#202b22); } html[data-theme="dark"] .rooms { background: #151b18; } html[data-theme="dark"] .room { border-color: #3a4a40; background: linear-gradient(145deg,#202923,#18211d); box-shadow: 0 12px 30px #0004; } html[data-theme="dark"] .room:hover { border-color: #758f62; } html[data-theme="dark"] .room-label, html[data-theme="dark"] .count, html[data-theme="dark"] .edit-room summary, html[data-theme="dark"] .residents > strong { color: #aebdb4; } html[data-theme="dark"] .room-number, html[data-theme="dark"] h1, html[data-theme="dark"] h2, html[data-theme="dark"] .brand strong { color: #f3f7f4; } html[data-theme="dark"] .room-name { color: #e2bd67; } html[data-theme="dark"] .edit-room { border-color: #35413b; } html[data-theme="dark"] .resident { border-color: #35413b; background: #202923; } html[data-theme="dark"] .resident span:nth-child(2) { color: #e3eee6; } html[data-theme="dark"] .resident-actions button { color: #d7e1da; background: #26312b; border-color: #4a5a50; } html[data-theme="dark"] input, html[data-theme="dark"] select, html[data-theme="dark"] .top-search { color: #f3f7f4; background: #202923; border-color: #4a5a50; }
        .add-panel { box-shadow: var(--shadow); }
        .add-form input, .edit-form input, .edit-form select { border-color: #dfe7d9; border-radius: 9px; }
        .button.primary { box-shadow: 0 7px 18px #17201d20; }
