<body>
    <header class="topbar"><a class="brand" href="{{ route('admin.dashboard') }}"><img src="{{ asset('images/logo-siap-kukar.png') }}" alt="Logo Asrama Putri Junjung Buyah Kukar YK"><span>Asrama Putri Junjung Buyah Kukar YK</span><span>›</span><strong>Kelola Kamar</strong></a><div class="top-search"><span>⌕</span><input placeholder="Cari kamar, penghuni..."><span class="shortcut">Ctrl K</span></div><div class="top-actions"><button class="icon-button" type="button" aria-label="Notifikasi">♧</button><button class="icon-button" type="button" id="theme-toggle" aria-label="Ganti mode warna">☼</button></div></header>
    <main>
        <div class="page-head"><div><h1>Kelola Kamar</h1><p class="intro">Kelola ketersediaan kamar dan penempatan penghuni asrama.</p></div><div class="head-actions"><a class="button" href="{{ route('admin.dashboard') }}">Dashboard</a><button class="button primary" id="add-button" type="button">＋ Tambah Kamar</button></div></div>
        @if (session('success')) <div class="notice">{{ session('success') }}</div> @endif @if ($errors->any()) <div class="errors"><ul>@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div> @endif
        <section class="add-panel" id="add-panel"><h2>Tambah Kamar</h2><form class="add-form" method="POST" action="{{ route('admin.kamar.store') }}">@csrf<label>Nomor Kamar<input name="nomor_kamar" value="{{ old('nomor_kamar') }}" required></label><button class="button primary" type="submit">Simpan Kamar</button></form></section>
        <section class="panel"><div class="panel-top"><nav class="tabs"><a class="tab {{ request('status', 'semua') === 'semua' ? 'active' : '' }}" href="{{ route('admin.kamar.index', ['status' => 'semua']) }}">Semua</a><a class="tab {{ request('status') === 'tersedia' ? 'active' : '' }}" href="{{ route('admin.kamar.index', ['status' => 'tersedia']) }}">Tersedia</a><a class="tab {{ request('status') === 'hampir_penuh' ? 'active' : '' }}" href="{{ route('admin.kamar.index', ['status' => 'hampir_penuh']) }}">Hampir Penuh</a><a class="tab {{ request('status') === 'penuh' ? 'active' : '' }}" href="{{ route('admin.kamar.index', ['status' => 'penuh']) }}">Penuh</a></nav><span class="count">Menampilkan {{ $kamars->count() }} kamar.</span></div><div class="rooms">@foreach ($kamars as $kamar) @php($terisi = $kamar->terisi) @php($persentase = $kamar->kapasitas ? min(100, ($terisi / $kamar->kapasitas) * 100) : 0) @php($status = $kamar->status !== 'tersedia' ? ucfirst($kamar->status) : ($terisi >= $kamar->kapasitas ? 'Penuh' : ($terisi > 0 ? 'Hampir Penuh' : 'Tersedia')))<article class="room"><div class="room-head"><div><div class="room-number">Kamar {{ $kamar->nomor_kamar }}</div>@if($kamar->nama_kamar)<div class="room-name">{{ $kamar->nama_kamar }}</div>@endif<span class="room-label">{{ $terisi }}/{{ $kamar->kapasitas }} penghuni</span></div><span class="status {{ $status === 'Penuh' ? 'full' : ($status === 'Hampir Penuh' ? 'almost' : '') }}">{{ $status }}</span></div><div class="bar"><span style="width: {{ $persentase }}%"></span></div><details class="edit-room"><summary>Edit kamar</summary><form class="edit-form" method="POST" action="{{ route('admin.kamar.update', $kamar) }}">@csrf @method('PATCH')<label>Nama kamar<input name="nama_kamar" value="{{ $kamar->nama_kamar }}" placeholder="Contoh: Mawar"></label><label>Nomor kamar<input name="nomor_kamar" value="{{ $kamar->nomor_kamar }}" required></label><label>Kapasitas<input type="number" name="kapasitas" value="{{ $kamar->kapasitas }}" min="1" max="20" required></label><label>Terisi<input type="number" name="terisi" value="{{ $terisi }}" min="0" max="{{ $kamar->kapasitas }}" required></label><label>Status<select name="status"><option value="tersedia" @selected($kamar->status === 'tersedia')>Tersedia</option><option value="diperbaiki" @selected($kamar->status === 'diperbaiki')>Sedang diperbaiki</option><option value="ditutup" @selected($kamar->status === 'ditutup')>Ditutup</option></select></label><button class="button primary" type="submit">Simpan Perubahan</button></form></details><div class="residents"><strong>Penghuni kamar</strong>@foreach($kamar->penghunis as $penghuni)<div class="resident"><span class="avatar">{{ strtoupper(substr($penghuni->name, 0, 1)) }}</span><span>{{ $penghuni->name }}</span><div class="resident-actions"><details><summary>Pindah</summary><form method="POST" action="{{ route('admin.kamar.penghuni.move', $penghuni) }}">@csrf @method('PATCH')<select name="kamar_id" required>@foreach($kamars as $tujuan)<option value="{{ $tujuan->id }}" @selected($tujuan->id === $kamar->id)>Kamar {{ $tujuan->nomor_kamar }}</option>@endforeach</select><button type="submit">Pindah</button></form></details><form method="POST" action="{{ route('admin.kamar.penghuni.remove', $penghuni) }}" onsubmit="return confirm('Keluarkan penghuni dari kamar?')">@csrf @method('PATCH')<button type="submit">Keluarkan</button></form></div></div>@endforeach @if($kamar->penghunis->isEmpty())<div class="empty">Belum ada penghuni.</div>@endif</div></article>@endforeach @if($kamars->isEmpty())<div class="empty">Belum ada data kamar.</div>@endif</div></section>
    </main>
    <script>document.querySelector('#add-button').addEventListener('click', () => document.querySelector('#add-panel').classList.toggle('open'));</script>
<script>const themeToggle=document.querySelector('#theme-toggle');const setTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';themeToggle.textContent=dark?'☀':'☾';themeToggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('admin-theme',next);themeToggle.textContent=next==='dark'?'☀':'☾';};};setTheme();</script></body>
